AND EXISTS (SELECT 1 FROM course scope_course WHERE scope_course.id=${courseColumn}


        AND scope_course.teacher_id=#{scopeUserId}


        AND scope_course.is_open=1 AND EXISTS (SELECT 1 FROM course_enrollment scope_enrollment WHERE
        scope_enrollment.course_id=scope_course.id AND scope_enrollment.student_id=#{scopeUserId})

    AND 1=0

)
